import pandas as pdimport geopandas as gpdfrom shapely.geometry import LineStringimport os"""create_geojson.pyThis utility script reads the raw node and edge CSV files from the LPSimsimulation data and generates a GeoJSON file representing the road network'sgeometry. This GeoJSON file can then be used for spatial analysis and plotting.This script only needs to be run once."""# --- Configuration ---# Please ensure these paths point to your actual data files.# I have pre-filled them based on the paths you provided.LIVINGCITY_DIR = 'LivingCity'NETWORK_DATA_PATH = os.path.join(LIVINGCITY_DIR, 'berkeley_2018', 'full_network')  # Adjusted to match .iniNODES_CSV_PATH = os.path.join(NETWORK_DATA_PATH, 'nodes.csv')EDGES_CSV_PATH = os.path.join(NETWORK_DATA_PATH, 'edges.csv')# Output filenameGEOJSON_OUTPUT_PATH = "network.geojson"def create_network_geojson():    """    Reads node and edge data and creates a GeoJSON file.    """    print("--- Starting GeoJSON Generation ---")    # 1. Check if input files exist    if not os.path.exists(NODES_CSV_PATH) or not os.path.exists(EDGES_CSV_PATH):        print(f"ERROR: Cannot find input files.")        print(f"  - Checked for nodes at: {NODES_CSV_PATH}")        print(f"  - Checked for edges at: {EDGES_CSV_PATH}")        print("Please verify the paths in the script.")        return    # 2. Load nodes data (ID, Longitude, Latitude)    print(f"Reading nodes from '{NODES_CSV_PATH}'...")    nodes_df = pd.read_csv(NODES_CSV_PATH)    # Create a dictionary for fast coordinate lookup: {node_id: (longitude, latitude)}    # The 'index' column from nodes.csv corresponds to 'u' and 'v' in edges.csv    node_coords = {row['index']: (row['x'], row['y']) for index, row in nodes_df.iterrows()}    print(f"Loaded {len(node_coords)} node coordinates.")    # 3. Load edges data    print(f"Reading edges from '{EDGES_CSV_PATH}'...")    edges_df = pd.read_csv(EDGES_CSV_PATH)    print(f"Loaded {len(edges_df)} edges.")    # 4. Create LineString geometries for each edge    print("Creating geometries for each edge (this might take a moment)...")    def create_linestring(row):        # Get coordinates for the start (u) and end (v) nodes of the edge        start_node_id = row['u']        end_node_id = row['v']        start_coord = node_coords.get(start_node_id)        end_coord = node_coords.get(end_node_id)        if start_coord and end_coord:            return LineString([start_coord, end_coord])        return None    # Apply the function to each row of the edges dataframe    edges_df['geometry'] = edges_df.apply(create_linestring, axis=1)    # 5. Create the GeoDataFrame    print("Constructing GeoDataFrame...")    # Select only the necessary columns for the final file    # 'uniqueid' is the crucial column that links simulation results to geometry    gdf = gpd.GeoDataFrame(edges_df[['uniqueid', 'geometry']], geometry='geometry')    gdf.set_crs("EPSG:4326", inplace=True)  # Set coordinate system to WGS84 (lat/lon)    # 6. Save to GeoJSON file    print(f"Saving GeoDataFrame to '{GEOJSON_OUTPUT_PATH}'...")    gdf.to_file(GEOJSON_OUTPUT_PATH, driver='GeoJSON')    print("\n--- SUCCESS! ---")    print(f"GeoJSON network file has been created at '{GEOJSON_OUTPUT_PATH}'.")    print("You can now use this file in the main analysis script.")if __name__ == "__main__":    create_network_geojson()